INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'A ORAÇÃO DA TUA IGREJA','A ORAÇÃO DA TUA IGREJA','A ORAÇÃO DA TUA IGREJA\nALCANÇA O CÉU.\nEM MEIO AOS MEUS TEMORES,\nPROSTRO-ME AOS TEUS PÉS,\nPOIS TUA PALAVRA ME DIZ:\n\nCORO\nSE ME HUMILHAR E ORAR\nE BUSCAR A TUA FACE,\nME ARREPENDER DE MEUS\nCAMINHOS MAUS,\n(M) ENTÃO, TU VIRÁS\n(H) E SARARÁS A TERRA,\nENTÃO, TU VIRÁS E SARARÁS\nMEU CORAÇÃO.\n\nSE EU ORAR, (SE EU ORAR)\nTU ME ESCUTARÁS\nE O CÉU SE ABRIRÁ PRA MIM.\nSE EU ORAR, (SE EU ORAR)\nENTÃO, SABEREI QUE NÃO É O FIM.\nSE EU ORAR, SE EU ORAR,\n\nMINHA ALMA INTEIRA SE RENOVARÁ,\nMEU CORAÇÃO DESCANSARÁ EM TI\nE OS MEUS OLHOS VERÃO\nO TEU AGIR EM MEU FAVOR!\n\nINSTRUMENTOS\n\nCORO\nSE ME HUMILHAR E ORAR E BUSCAR A TUA FACE,\nME ARREPENDER DE MEUS CAMINHOS MAUS,\n(M) ENTÃO, TU VIRÁS\n(H) E SARARÁS A TERRA,\nENTÃO, TU VIRÁS E SARARÁS MEU CORAÇÃO.\n\nSE EU ORAR, (SE EU ORAR)\nTU ME ESCUTARÁS\nE O CÉU SE ABRIRÁ PRA MIM.\nSE EU ORAR, (SE EU ORAR)\nENTÃO, SABEREI QUE NÃO É O FIM.\n\nFINAL:\nSE EU ORAR, SE EU ORAR,\nSE EU ORAR.','A ORAÇÃO DA TUA IGREJA\nALCANÇA O CÉU.\nEM MEIO AOS MEUS TEMORES,\nPROSTRO-ME AOS TEUS PÉS,\nPOIS TUA PALAVRA ME DIZ:<coro>\nSE ME HUMILHAR E ORAR\nE BUSCAR A TUA FACE,\nME ARREPENDER DE MEUS\nCAMINHOS MAUS,\n<m> ENTÃO, TU VIRÁS\n<h> E SARARÁS A TERRA,\nENTÃO, TU VIRÁS E SARARÁS\nMEU CORAÇÃO.\n\nSE EU ORAR, (SE EU ORAR)\nTU ME ESCUTARÁS\nE O CÉU SE ABRIRÁ PRA MIM.\nSE EU ORAR, (SE EU ORAR)\nENTÃO, SABEREI QUE NÃO É O FIM.\nSE EU ORAR, SE EU ORAR,\n\nMINHA ALMA INTEIRA SE RENOVARÁ,\nMEU CORAÇÃO DESCANSARÁ EM TI\nE OS MEUS OLHOS VERÃO\nO TEU AGIR EM MEU FAVOR!\n\nINSTRUMENTOS<coro>\nSE ME HUMILHAR E ORAR E BUSCAR A TUA FACE,\nME ARREPENDER DE MEUS CAMINHOS MAUS,\n<m> ENTÃO, TU VIRÁS\n<h> E SARARÁS A TERRA,\nENTÃO, TU VIRÁS E SARARÁS MEU CORAÇÃO.\n\nSE EU ORAR, (SE EU ORAR)\nTU ME ESCUTARÁS\nE O CÉU SE ABRIRÁ PRA MIM.\nSE EU ORAR, (SE EU ORAR)\nENTÃO, SABEREI QUE NÃO É O FIM.\n<final>SE EU ORAR, SE EU ORAR,\nSE EU ORAR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'A PALAVRA DE PODER','A PALAVRA DE PODER','A PALAVRA DE PODER SAIU DO SEU TRONO\nORDENANDO TODA CRIAÇÃO.\nHAJA LUZ! (HOUVE LUZ)\nHAJA LUA E ESTRELAS!\nSUA GLÓRIA ESTENDIDA NO CÉU.\n\nO SEU POVO GUIOU\nCOM A NUVEM DE DIA\nE A NOITE O FOGO NÃO FALTOU.\n\nCORO\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nA PALAVRA DE PODER SAIU DO SEU TRONO\nORDENANDO TODA CRIAÇÃO. (TODA CRIAÇÃO)\nHAJA LUZ! (HOUVE LUZ)\nHAJA LUA E ESTRELAS!\nSUA GLÓRIA ESTENDIDA NO CÉU.\n\nO SEU POVO GUIOU\nCOM A NUVEM DE DIA\nE A NOITE O FOGO NÃO FALTOU.\n\nCORO\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nCREIA, CRISTO PODE TRANSFORMAR\nSUA TRISTEZA EM ALEGRIA,\nVIDA NOVA LHE DARÁ.\nCREIA, JESUS CRISTO NÃO MUDOU.\nELE É O MESMO EM NOSSOS DIAS,\nELE É O SALVADOR.\n\nCORO\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nINSTRUMENTOS\n\nCORO\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nFINAL:\nTUDO ISSO PELA PALAVRA DO SENHOR.','A PALAVRA DE PODER SAIU DO SEU TRONO\nORDENANDO TODA CRIAÇÃO.\nHAJA LUZ! (HOUVE LUZ)\nHAJA LUA E ESTRELAS!\nSUA GLÓRIA ESTENDIDA NO CÉU.\n\nO SEU POVO GUIOU\nCOM A NUVEM DE DIA\nE A NOITE O FOGO NÃO FALTOU.<coro>\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nA PALAVRA DE PODER SAIU DO SEU TRONO\nORDENANDO TODA CRIAÇÃO. (TODA CRIAÇÃO)\nHAJA LUZ! (HOUVE LUZ)\nHAJA LUA E ESTRELAS!\nSUA GLÓRIA ESTENDIDA NO CÉU.\n\nO SEU POVO GUIOU\nCOM A NUVEM DE DIA\nE A NOITE O FOGO NÃO FALTOU.<coro>\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nCREIA, CRISTO PODE TRANSFORMAR\nSUA TRISTEZA EM ALEGRIA,\nVIDA NOVA LHE DARÁ.\nCREIA, JESUS CRISTO NÃO MUDOU.\nELE É O MESMO EM NOSSOS DIAS,\nELE É O SALVADOR.<coro>\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n\nINSTRUMENTOS<coro>\nO MAR SE ABRIU, ISRAEL PASSOU,\nO SURDO OUVIU, O CEGO ENXERGOU;\nTUDO ISSO PELA PALAVRA DO SENHOR.\n<final>TUDO ISSO PELA PALAVRA DO SENHOR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'ABRE O CORAÇÃO','ABRE O CORAÇÃO','ABRE O CORAÇÃO, DEIXA O SENHOR ENTRAR,\nE MODIFICAR PRA SEMPRE O TEU VIVER,\nE NESTE LOUVOR DEUS VAI SE REVELAR,\nPARA RESTAURAR TEU CORAÇÃO.\n\nCORO\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPRA PODER AGIR EM TEU FAVOR.\n(PARA AGIR EM TEU FAVOR)\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPARA DERRAMAR O SEU AMOR.\n\nABRE O CORAÇÃO, DEIXA O SENHOR ENTRAR,\n(DEIXA ENTRAR)\nE MODIFICAR PRA SEMPRE O TEU VIVER.\n(O TEU VIVER)\nE NESTE LOUVOR DEUS VAI SE REVELAR,\n(SE REVELAR)\nPARA RESTAURAR TEU CORAÇÃO.\n\nCORO (2X)\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPRA PODER AGIR EM TEU FAVOR.\n(PARA AGIR EM TEU FAVOR)\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPARA DERRAMAR O SEU AMOR.','ABRE O CORAÇÃO, DEIXA O SENHOR ENTRAR,\nE MODIFICAR PRA SEMPRE O TEU VIVER,\nE NESTE LOUVOR DEUS VAI SE REVELAR,\nPARA RESTAURAR TEU CORAÇÃO.<coro>\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPRA PODER AGIR EM TEU FAVOR.\n(PARA AGIR EM TEU FAVOR)\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPARA DERRAMAR O SEU AMOR.\n\nABRE O CORAÇÃO, DEIXA O SENHOR ENTRAR,\n(DEIXA ENTRAR)\nE MODIFICAR PRA SEMPRE O TEU VIVER.\n(O TEU VIVER)\nE NESTE LOUVOR DEUS VAI SE REVELAR,\n(SE REVELAR)\nPARA RESTAURAR TEU CORAÇÃO.<coro tipo="2X">\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPRA PODER AGIR EM TEU FAVOR.\n(PARA AGIR EM TEU FAVOR)\nO SENHOR SÓ QUER DE TI SINCERIDADE,\n(ELE VÊ TEU CORAÇÃO)\nPARA DERRAMAR O SEU AMOR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'ALELUIA, ALELUIA, ALELUIA','ALELUIA, ALELUIA, ALELUIA','(2x)\nALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA.\n\n(2x)\nPOIS, O SENHOR ONIPOTENTE REINA\nALELUIA, ALELUIA, ALELUIA, ALELUIA\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\nALELUIA, ALELUIA (ALELUIA, ALELUIA)\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\nALELUIA.\n\nO REINO DESTE MUNDO \nJÁ PASSOU\n\nA SER DE NOSSO SENHOR,\nE DE SEU CRISTO (2X)\n\nE ELE REINARÁ PARA SEMPRE\n\nE ELE REINARÁ PARA SEMPRE\n(E REINARÁ, E REINARÁ)\n\nE ELE REINARÁ PARA SEMPRE\n(E REINARÁ, PRA SEMPRE E SEMPRE)\n\nE ELE REINARÁ PARA SEMPRE\n(PRA SEMPRE, PRA SEMPRE, \nREINARÁ, PRA SEMPREE SEMPRE)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR.\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR.\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR. REI DOS REIS, E GRANDE SENHOR\n\nREI DOS REIS, E REINARÁ\n(E ELE REINARÁ, E REINARÁ)\n\nREI DOS REIS, E REINARÁ\n(E REINARÁ PARA SEMPRE)\n\nE ELE REINARÁ PARA SEMPRE.\n(E REINARÁ PARA SEMPRE)\n\nREI DOS REIS, (PRA SEMPRE E SEMPRE)\nE GRANDE SENHOR. (ALELUIA, ALELUIA)\n\nE ELE REINARÁ PARA SEMPRE,\nE SEMPRE\n\n(2X) \nREIS DOS REIS, E GRANDE SENHOR\n\nE ELE REINARÁ PARA SEMPRE.\n(E REINARÁ PARA SEMPRE)\n\nPRA SEMPRE E SEMPRE, (2X)\n(REI DOS REIS, E GRANDE SENHOR)\n\nFINAL\nALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA.','<bis tipo="2x">\nALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA.\n\n<bis tipo="2x">\nPOIS, O SENHOR ONIPOTENTE REINA\nALELUIA, ALELUIA, ALELUIA, ALELUIA\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\nALELUIA, ALELUIA (ALELUIA, ALELUIA)\n\nPOIS, O SENHOR ONIPOTENTE REINA\n(ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA)\nALELUIA.\n\nO REINO DESTE MUNDO \nJÁ PASSOU\n\nA SER DE NOSSO SENHOR,\nE DE SEU CRISTO <bis tipo="2x">\n\nE ELE REINARÁ PARA SEMPRE\n\nE ELE REINARÁ PARA SEMPRE\n(E REINARÁ, E REINARÁ)\n\nE ELE REINARÁ PARA SEMPRE\n(E REINARÁ, PRA SEMPRE E SEMPRE)\n\nE ELE REINARÁ PARA SEMPRE\n(PRA SEMPRE, PRA SEMPRE, \nREINARÁ, PRA SEMPREE SEMPRE)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR.\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR.\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nREI DOS REIS\n(PRA SEMPRE, E SEMPRE, ALELUIA, ALELUIA)\n\nE GRANDE SENHOR. REI DOS REIS, E GRANDE SENHOR\n\nREI DOS REIS, E REINARÁ\n(E ELE REINARÁ, E REINARÁ)\n\nREI DOS REIS, E REINARÁ\n(E REINARÁ PARA SEMPRE)\n\nE ELE REINARÁ PARA SEMPRE.\n(E REINARÁ PARA SEMPRE)\n\nREI DOS REIS, (PRA SEMPRE E SEMPRE)\nE GRANDE SENHOR. (ALELUIA, ALELUIA)\n\nE ELE REINARÁ PARA SEMPRE,\nE SEMPRE\n\n<bis tipo="2x"> \nREIS DOS REIS, E GRANDE SENHOR\n\nE ELE REINARÁ PARA SEMPRE.\n(E REINARÁ PARA SEMPRE)\n\nPRA SEMPRE E SEMPRE, <bis tipo="2x">\n(REI DOS REIS, E GRANDE SENHOR)\n<final>ALELUIA, ALELUIA, ALELUIA, ALELUIA, ALELUIA.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'AO NOSSO DEUS','AO NOSSO DEUS','AO NOSSO DEUS,\nQUE SE ASSENTA NO TRONO,\nE AO CORDEIRO PERTENCE A SALVAÇÃO;\n\nFINAL (BIS)\nE O LOUVOR, E A GLÓRIA,\nE A SABEDORIA, E AS AÇÕES\nDE GRAÇA, E A HONRA,\nE O PODER, E A FORÇA,\nSEJAM AO NOSSO DEUS\nPELOS SÉCULOS DOS SÉCULOS,\nAMÉM.','AO NOSSO DEUS,\nQUE SE ASSENTA NO TRONO,\nE AO CORDEIRO PERTENCE A SALVAÇÃO;\n<final><bis>\nE O LOUVOR, E A GLÓRIA,\nE A SABEDORIA, E AS AÇÕES\nDE GRAÇA, E A HONRA,\nE O PODER, E A FORÇA,\nSEJAM AO NOSSO DEUS\nPELOS SÉCULOS DOS SÉCULOS,\nAMÉM.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'AQUELE QUE HÁ DE VIR VIRÁ (VIVEREMOS PELA FÉ)','AQUELE QUE HÁ DE VIR VIRÁ (VIVEREMOS PELA FÉ)','AQUELE QUE HÁ DE VIR VIRÁ\nE NÃO TARDARÁ.\nO JUSTO VIVERÁ PELA FÉ\nE NÃO DEVE RECUAR.\n\nEM TUDO SOMOS ATRIBULADOS,\nPORÉM, NÃO ESTAMOS ANGUSTIADOS.\nO DEUS, QUE ONTEM DE MIM CUIDOU,\nHOJE E SEMPRE COMIGO ESTARÁ.\n\nCORO\nVIVEREMOS PELA FÉ,\nSABENDO QUE O NOSSO SENHOR VIVO ESTÁ\nE EM BREVE, (E EM BREVE)\nMUITO EM BREVE, (MUITO EM BREVE)\nAO CÉU NOS LEVARÁ!\n\nNÃO TEMAS OS TEMORES DA NOITE,\nO SENHOR CONTIGO ESTÁ.\nO DEUS, QUE ONTEM DE TI CUIDOU,\nHOJE E SEMPRE CONTIGO ESTARÁ.\n\nFINAL 2X\nVIVEREMOS PELA FÉ,\nSABENDO QUE O NOSSO SENHOR VIVO ESTÁ\nE EM BREVE, (E EM BREVE)\nMUITO EM BREVE, (MUITO EM BREVE)\nAO CÉU NOS LEVARÁ!','AQUELE QUE HÁ DE VIR VIRÁ\nE NÃO TARDARÁ.\nO JUSTO VIVERÁ PELA FÉ\nE NÃO DEVE RECUAR.\n\nEM TUDO SOMOS ATRIBULADOS,\nPORÉM, NÃO ESTAMOS ANGUSTIADOS.\nO DEUS, QUE ONTEM DE MIM CUIDOU,\nHOJE E SEMPRE COMIGO ESTARÁ.<coro>\nVIVEREMOS PELA FÉ,\nSABENDO QUE O NOSSO SENHOR VIVO ESTÁ\nE EM BREVE, (E EM BREVE)\nMUITO EM BREVE, (MUITO EM BREVE)\nAO CÉU NOS LEVARÁ!\n\nNÃO TEMAS OS TEMORES DA NOITE,\nO SENHOR CONTIGO ESTÁ.\nO DEUS, QUE ONTEM DE TI CUIDOU,\nHOJE E SEMPRE CONTIGO ESTARÁ.\n<final>2X\nVIVEREMOS PELA FÉ,\nSABENDO QUE O NOSSO SENHOR VIVO ESTÁ\nE EM BREVE, (E EM BREVE)\nMUITO EM BREVE, (MUITO EM BREVE)\nAO CÉU NOS LEVARÁ!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'ARREPENDEI-VOS','ARREPENDEI-VOS','(VARÕES)\nARREPENDEI-VOS PORQUE\nÉ CHEGADO O REINO DOS CÉUS.\nASSIM DISSE JESUS:\nVINDE APÓS MIM E EU VOS FAREI\nPESCADORES DE HOMENS.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO,\nLIBERTANDO DAS TREVAS O HOMEM, ENFIM.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ\n\nINSTRUMENTOS\n\n(VARÕES)\nE AGORA QUE MANIFESTOU SUA GLÓRIA\nPELO EVANGELHO ETERNO,\nCURARÁ NOSSA ENFERMIDADE\nE DARÁ A SUA PAZ.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO.\nLIBERTANDO DAS TREVAS O HOMEM, ENFIM.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ. (3X)','<h>\nARREPENDEI-VOS PORQUE\nÉ CHEGADO O REINO DOS CÉUS.\nASSIM DISSE JESUS:\nVINDE APÓS MIM E EU VOS FAREI\nPESCADORES DE HOMENS.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO,\nLIBERTANDO DAS TREVAS O HOMEM, ENFIM.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ\n<instrumentos>\n<h>\nE AGORA QUE MANIFESTOU SUA GLÓRIA\nPELO EVANGELHO ETERNO,\nCURARÁ NOSSA ENFERMIDADE\nE DARÁ A SUA PAZ.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO.\nLIBERTANDO DAS TREVAS O HOMEM, ENFIM.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ.\n\nUMA GRANDE LUZ SE MANIFESTOU\nAOS QUE ESTAVAM ASSENTADOS\nEM MEIO À ESCURIDÃO.\nESSA LUZ QUE RAIOU É JESUS.\nMANIFESTADO ESTÁ. <bis tipo="3x">',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'BASTA-NOS TUA GRAÇA SENHOR','BASTA-NOS TUA GRAÇA SENHOR','BASTA-NOS TUA GRAÇA,SENHOR!\nSUFICIENTE E IMERECIDO FAVOR.\nNÃO SOMOS MERECEDORES,\nMAS TEU AMOR NOS ALCANÇOU.\nO QUE PODEMOS TE OFERECER,\n(TEU AMOR NOS ALCANÇOU!)\nSE O QUE TEMOS PROVEIO DE TI?\nE SEM TI NADA SOMOS,\nA TUA GRAÇA NOS BASTA.\n\nBASTA-NOS TUA GRAÇA SENHOR!\nE OS NOSSOS PÉS NÃO VACILARÃO.\nCAMINHAREMOS SEGUROS,\nSUSTENTADOS POR TUA MÃO!\n\nO QUE PODEMOS TE OFERECER,\nSE O QUE TEMOS PROVEIO DE TI?\nE SEM TI NADA SOMOS,\nA TUA GRAÇA NOS BASTA.\nSACRIFÍCIOS DE LOUVOR\nÉ O QUE PODEMOS TE OFERECER,\n\nFINAL 2X\nPOIS TUDO O QUE SOMOS\nPELA GRAÇA VEIO DE TI.','BASTA-NOS TUA GRAÇA,SENHOR!\nSUFICIENTE E IMERECIDO FAVOR.\nNÃO SOMOS MERECEDORES,\nMAS TEU AMOR NOS ALCANÇOU.\nO QUE PODEMOS TE OFERECER,\n(TEU AMOR NOS ALCANÇOU!)\nSE O QUE TEMOS PROVEIO DE TI?\nE SEM TI NADA SOMOS,\nA TUA GRAÇA NOS BASTA.\n\nBASTA-NOS TUA GRAÇA SENHOR!\nE OS NOSSOS PÉS NÃO VACILARÃO.\nCAMINHAREMOS SEGUROS,\nSUSTENTADOS POR TUA MÃO!\n\nO QUE PODEMOS TE OFERECER,\nSE O QUE TEMOS PROVEIO DE TI?\nE SEM TI NADA SOMOS,\nA TUA GRAÇA NOS BASTA.\nSACRIFÍCIOS DE LOUVOR\nÉ O QUE PODEMOS TE OFERECER,\n<final>2X\nPOIS TUDO O QUE SOMOS\nPELA GRAÇA VEIO DE TI.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'CANTARES 2','CANTARES 2','JESUS, ÉS A ROCHA,\nÉS O LÍRIO, A ROSA DE SAROM,\nOS ESPINHOS NÃO PODEM AFASTAR-ME,\nEM TUA SOMBRA QUERO DESCANSAR.\nSUSTENTA-ME E CONFORTA-ME\nCOM TUAS MÃOS,\nPOIS MINHA ALMA ANSEIA POR TI.\nCERTAMENTE ELE CEDO VEM!\n\nCORO\nEI-LO AÍ!\nVEM SALTANDO SOBRE OS MONTES!\nMEU AMADO ME FALA E DIZ:\nIGREJA MINHA, LEVANTA-TE E VEM!\nNÃO DESPERTEIS O MEU AMOR\nATÉ QUE QUEIRA.\nNOSSAS VINHAS JÁ ESTÃO EM FLOR,\nE O ESTANDARTE EM MIM É O AMOR.\n\nJESUS, ÉS A ROCHA,\nÉS O LÍRIO, A ROSA DE SAROM,\nOS ESPINHOS NÃO PODEM AFASTAR-ME,\nEM TUA SOMBRA QUERO DESCANSAR.\nSUSTENTA-ME E CONFORTA-ME\nCOM TUAS MÃOS,\nPOIS MINHA ALMA ANSEIA POR TI.\nCERTAMENTE ELE CEDO VEM!\n\nCORO\nEI-LO AÍ!\nVEM SALTANDO SOBRE OS MONTES!\nMEU AMADO ME FALA E DIZ:\nIGREJA MINHA, LEVANTA-TE E VEM!\nNÃO DESPERTEIS O MEU AMOR\nATÉ QUE QUEIRA.\nNOSSAS VINHAS JÁ ESTÃO EM FLOR,\nE O ESTANDARTE EM MIM É O AMOR.\n\nINSTRUMENTOS\n\nFINAL:\n(H) ELE VEM! ELE VEM!\nEI-LO AÍ! ELE VEM! VEM, VEM!\n(ELE VEM!)\nEI-LO AÍ! ELE VEM! VEM, VEM!\nEI-LO AÍ! ELE VEM! VEM, VEM!','JESUS, ÉS A ROCHA,\nÉS O LÍRIO, A ROSA DE SAROM,\nOS ESPINHOS NÃO PODEM AFASTAR-ME,\nEM TUA SOMBRA QUERO DESCANSAR.\nSUSTENTA-ME E CONFORTA-ME\nCOM TUAS MÃOS,\nPOIS MINHA ALMA ANSEIA POR TI.\nCERTAMENTE ELE CEDO VEM!<coro>\nEI-LO AÍ!\nVEM SALTANDO SOBRE OS MONTES!\nMEU AMADO ME FALA E DIZ:\nIGREJA MINHA, LEVANTA-TE E VEM!\nNÃO DESPERTEIS O MEU AMOR\nATÉ QUE QUEIRA.\nNOSSAS VINHAS JÁ ESTÃO EM FLOR,\nE O ESTANDARTE EM MIM É O AMOR.\n\nJESUS, ÉS A ROCHA,\nÉS O LÍRIO, A ROSA DE SAROM,\nOS ESPINHOS NÃO PODEM AFASTAR-ME,\nEM TUA SOMBRA QUERO DESCANSAR.\nSUSTENTA-ME E CONFORTA-ME\nCOM TUAS MÃOS,\nPOIS MINHA ALMA ANSEIA POR TI.\nCERTAMENTE ELE CEDO VEM!<coro>\nEI-LO AÍ!\nVEM SALTANDO SOBRE OS MONTES!\nMEU AMADO ME FALA E DIZ:\nIGREJA MINHA, LEVANTA-TE E VEM!\nNÃO DESPERTEIS O MEU AMOR\nATÉ QUE QUEIRA.\nNOSSAS VINHAS JÁ ESTÃO EM FLOR,\nE O ESTANDARTE EM MIM É O AMOR.\n<instrumentos>\n<final><h> ELE VEM! ELE VEM!\nEI-LO AÍ! ELE VEM! VEM, VEM!\n(ELE VEM!)\nEI-LO AÍ! ELE VEM! VEM, VEM!\nEI-LO AÍ! ELE VEM! VEM, VEM!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'CELEBRAI!','CELEBRAI!','CELEBRAI COM JÚBILO AO SENHOR\nOS MORADORES DA TERRA.\nSERVI AO SENHOR COM ALEGRIA\nAPRESENTAI-VOS COM CANTO.\nSABEIS QUE O SENHOR É DEUS\nE COMO SEU POVO NOS ELEGEU,\nSOMOS OVELHAS DO SEU PASTO!\n\nENTRAI POR SUAS PORTAS COM LOUVOR\nE EM SEUS ÁTRIOS COM CÂNTICO.\nLOUVAI-O E BENDIZEI O SEU NOME,\nPOIS O SENHOR É BOM.\nETERNA É A SUA MISERICÓRDIA\nE A SUA VERDADE\nÉ ENTENDIDA E ESTENDIDA\nDE GERAÇÃO A GERAÇÃO!\n\nCELEBRAI COM JÚBILO AO SENHOR\nOS MORADORES DA TERRA.\nSERVI AO SENHOR COM ALEGRIA\nAPRESENTAI-VOS COM CANTO.\nSABEIS QUE O SENHOR É DEUS\nE COMO SEU POVO NOS ELEGEU,\nSOMOS OVELHAS DO SEU PASTO!\n\nENTRAI POR SUAS PORTAS COM LOUVOR\nE EM SEUS ÁTRIOS COM CÂNTICO.\nLOUVAI-O E BENDIZEI O SEU NOME,\nPOIS O SENHOR É BOM.\nETERNA É A SUA MISERICÓRDIA\nE A SUA VERDADE\nÉ ENTENDIDA E ESTENDIDA\nDE GERAÇÃO A GERAÇÃO!\n\nFINAL:\nSOMOS OVELHAS DO SEU PASTO!\nDE GERAÇÃO A GERAÇÃO!','CELEBRAI COM JÚBILO AO SENHOR\nOS MORADORES DA TERRA.\nSERVI AO SENHOR COM ALEGRIA\nAPRESENTAI-VOS COM CANTO.\nSABEIS QUE O SENHOR É DEUS\nE COMO SEU POVO NOS ELEGEU,\nSOMOS OVELHAS DO SEU PASTO!\n\nENTRAI POR SUAS PORTAS COM LOUVOR\nE EM SEUS ÁTRIOS COM CÂNTICO.\nLOUVAI-O E BENDIZEI O SEU NOME,\nPOIS O SENHOR É BOM.\nETERNA É A SUA MISERICÓRDIA\nE A SUA VERDADE\nÉ ENTENDIDA E ESTENDIDA\nDE GERAÇÃO A GERAÇÃO!\n\nCELEBRAI COM JÚBILO AO SENHOR\nOS MORADORES DA TERRA.\nSERVI AO SENHOR COM ALEGRIA\nAPRESENTAI-VOS COM CANTO.\nSABEIS QUE O SENHOR É DEUS\nE COMO SEU POVO NOS ELEGEU,\nSOMOS OVELHAS DO SEU PASTO!\n\nENTRAI POR SUAS PORTAS COM LOUVOR\nE EM SEUS ÁTRIOS COM CÂNTICO.\nLOUVAI-O E BENDIZEI O SEU NOME,\nPOIS O SENHOR É BOM.\nETERNA É A SUA MISERICÓRDIA\nE A SUA VERDADE\nÉ ENTENDIDA E ESTENDIDA\nDE GERAÇÃO A GERAÇÃO!\n<final>SOMOS OVELHAS DO SEU PASTO!\nDE GERAÇÃO A GERAÇÃO!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'CONHEÇAMOS E PROSSIGAMOS','CONHEÇAMOS E PROSSIGAMOS','CONHEÇAMOS E PROSSIGAMOS EM CONHECER AO SENHOR,  \nCOMO A ALVA SERÁ A SUA SAÍDA;  \nE ELE A NÓS VIRÁ COMO A CHUVA QUE REGA A TERRA.\n\nQUEREMOS TE CONHECER, Ó DEUS, CONHECER MAIS E MAIS DE TI;  \nQUEREMOS VER A TUA FACE, CONTEMPLAR O TEU AMOR,  \nQUEREMOS CONHECER MAIS E MAIS TUA VONTADE, SENHOR.\n\nREGA A NOSSA VIDA, SENHOR,  \nCOMO A CHUVA SERÔDIA QUE REGA A TERRA;  \nDERRAMA EM NOSSOS CORAÇÕES A CHUVA DA TUA UNÇÃO.\n\nCONHEÇAMOS E PROSSIGAMOS EM CONHECER AO SENHOR,  \nCOMO A ALVA SERÁ A SUA SAÍDA;  \nE ELE A NÓS VIRÁ COMO A CHUVA QUE REGA A TERRA.  \nRENOVA OS NOSSOS CORAÇÕES, RENOVA A NOSSA FÉ;  \nCOMO A ALVA SERÁ A SUA SAÍDA.\n\nFINAL  \nE ELE A NÓS VIRÁ, JESUS VIRÁ, JESUS VIRÁ','CONHEÇAMOS E PROSSIGAMOS EM CONHECER AO SENHOR,  \nCOMO A ALVA SERÁ A SUA SAÍDA;  \nE ELE A NÓS VIRÁ COMO A CHUVA QUE REGA A TERRA.\n\nQUEREMOS TE CONHECER, Ó DEUS, CONHECER MAIS E MAIS DE TI;  \nQUEREMOS VER A TUA FACE, CONTEMPLAR O TEU AMOR,  \nQUEREMOS CONHECER MAIS E MAIS TUA VONTADE, SENHOR.\n\nREGA A NOSSA VIDA, SENHOR,  \nCOMO A CHUVA SERÔDIA QUE REGA A TERRA;  \nDERRAMA EM NOSSOS CORAÇÕES A CHUVA DA TUA UNÇÃO.\n\nCONHEÇAMOS E PROSSIGAMOS EM CONHECER AO SENHOR,  \nCOMO A ALVA SERÁ A SUA SAÍDA;  \nE ELE A NÓS VIRÁ COMO A CHUVA QUE REGA A TERRA.  \nRENOVA OS NOSSOS CORAÇÕES, RENOVA A NOSSA FÉ;  \nCOMO A ALVA SERÁ A SUA SAÍDA.\n<final>E ELE A NÓS VIRÁ, JESUS VIRÁ, JESUS VIRÁ',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'CREIO NESTE DEUS (QUEM É COMO O SENHOR?)','CREIO NESTE DEUS (QUEM É COMO O SENHOR?)','CREIO NESTE DEUS, DEUS TÃO PODEROSO\nEL SHADAY, JEOVÁ JIREH, O GRANDE EU SOU\nQUE LIVROU A DANIEL E A ELIAS RESPONDEU COM FOGO\nELE ABRIU O MAR VERMELHO, LIBERTOU SEU POVO.\nMUDOU A MINHA HISTÓRIA\nME FEZ UM VENCEDOR!\nEU CREIO NESTE DEUS\nETERNO, FIEL AMIGO, MEU PROTETOR.\n\nCORO 2X\nELE ABRE OS MARES PARA MIM\nE ME TIRA DA COVA DOS LEÕES\nSIM, DEUS OUVE A VOZ DO MEU CLAMOR\nPOSSO CRER! INCOMPARÁVEL É MEU DEUS\nO GRANDE EU SOU, DEUS VIVO\nQUEM É COMO O SENHOR?\nQUEM É COMO O SENHOR, INCOMPARÁVEL DEUS EL SHADAY\nQUEM É COMO O SENHOR, INCOMPARÁVEL DEUS EL SHADAY.\n\nFINAL 2X\nQUEM É COMO O SENHOR, (ELOHIM ADONAI)\nINCOMPARÁVEL DEUS EL SHADAY (JEOVÁ SHALOM, EL SHADAY)\nQUEM É COMO O SENHOR?','CREIO NESTE DEUS, DEUS TÃO PODEROSO\nEL SHADAY, JEOVÁ JIREH, O GRANDE EU SOU\nQUE LIVROU A DANIEL E A ELIAS RESPONDEU COM FOGO\nELE ABRIU O MAR VERMELHO, LIBERTOU SEU POVO.\nMUDOU A MINHA HISTÓRIA\nME FEZ UM VENCEDOR!\nEU CREIO NESTE DEUS\nETERNO, FIEL AMIGO, MEU PROTETOR.<coro tipo="2X">\nELE ABRE OS MARES PARA MIM\nE ME TIRA DA COVA DOS LEÕES\nSIM, DEUS OUVE A VOZ DO MEU CLAMOR\nPOSSO CRER! INCOMPARÁVEL É MEU DEUS\nO GRANDE EU SOU, DEUS VIVO\nQUEM É COMO O SENHOR?\nQUEM É COMO O SENHOR, INCOMPARÁVEL DEUS EL SHADAY\nQUEM É COMO O SENHOR, INCOMPARÁVEL DEUS EL SHADAY.\n<final>2X\nQUEM É COMO O SENHOR, (ELOHIM ADONAI)\nINCOMPARÁVEL DEUS EL SHADAY (JEOVÁ SHALOM, EL SHADAY)\nQUEM É COMO O SENHOR?',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'CRISTO É VITÓRIA','CRISTO É VITÓRIA','CRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER;\nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\n\nTEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.\n\nCRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER;\nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\n\nTEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.\nPOR QUEM JÁ VENCEU NA CRUZ.','CRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER;\nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\n\nTEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.\n\nCRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER;\nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\n\nTEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.\nPOR QUEM JÁ VENCEU NA CRUZ.',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'DEUS DA PROVISÃO','DEUS DA PROVISÃO','PAI, MAIS UMA VEZ ESTOU AQUI,\nTÃO DEPENDENTE DO TEU AMOR,\nO TEU PODER ME PÕE DE PÉ.\nTÃO FRÁGIL SOU,\nMAS TUA BONDADE ME SUSTENTA\nPOR ONDE EU FOR.\n\nCORO 2X\nÉ NA TUA PRESENÇA QUE\nEU SOU FORTALECIDO;\nDESCANSAR EM TUA PROVISÃO\nÉ O QUE EU PRECISO.\n\nACALMA O MEU CORAÇÃO,\nPOIS ABRIGO ENCONTRO EM TEUS BRAÇOS.\n\nINSTRUMENTOS\n\nDEUS, ABRE MEUS OLHOS\nPARA QUE EU POSSA VER\nQUE OS TEUS PLANOS SÃO MAIORES\nQUE OS MEUS.\nDÁ-ME MAIS FÉ PARA CRER.\n“EU SOU O TEU DEUS, QUE FALA CONTIGO,\nO TEU CAMINHO TENHO EM MINHAS MÃOS”.\n\nCORO 2X\nÉ NA TUA PRESENÇA QUE\nEU SOU FORTALECIDO;\nDESCANSAR EM TUA PROVISÃO\nÉ O QUE EU PRECISO.\n\nPOR ISSO EU CANTO:\nA TI PERTENCE TODO O LOUVOR.\n(HONRA E ADORAÇÃO)\nSANTO, SANTO, SANTO É O SENHOR.\n(GLÓRIA AO QUE É SANTO)\n\nA TI PERTENCE TODO O LOUVOR.\n(HONRA E ADORAÇÃO)\nSANTO, SANTO, SANTO É O SENHOR.\n(GLÓRIA AO QUE É SANTO)\n\nFINAL:\nSANTO, SANTO, SANTO É O SENHOR. (3x)','PAI, MAIS UMA VEZ ESTOU AQUI,\nTÃO DEPENDENTE DO TEU AMOR,\nO TEU PODER ME PÕE DE PÉ.\nTÃO FRÁGIL SOU,\nMAS TUA BONDADE ME SUSTENTA\nPOR ONDE EU FOR.<coro tipo="2X">\nÉ NA TUA PRESENÇA QUE\nEU SOU FORTALECIDO;\nDESCANSAR EM TUA PROVISÃO\nÉ O QUE EU PRECISO.\n\nACALMA O MEU CORAÇÃO,\nPOIS ABRIGO ENCONTRO EM TEUS BRAÇOS.\n<instrumentos>\nDEUS, ABRE MEUS OLHOS\nPARA QUE EU POSSA VER\nQUE OS TEUS PLANOS SÃO MAIORES\nQUE OS MEUS.\nDÁ-ME MAIS FÉ PARA CRER.\n“EU SOU O TEU DEUS, QUE FALA CONTIGO,\nO TEU CAMINHO TENHO EM MINHAS MÃOS”.<coro tipo="2X">\nÉ NA TUA PRESENÇA QUE\nEU SOU FORTALECIDO;\nDESCANSAR EM TUA PROVISÃO\nÉ O QUE EU PRECISO.\n\nPOR ISSO EU CANTO:\nA TI PERTENCE TODO O LOUVOR.\n(HONRA E ADORAÇÃO)\nSANTO, SANTO, SANTO É O SENHOR.\n(GLÓRIA AO QUE É SANTO)\n\nA TI PERTENCE TODO O LOUVOR.\n(HONRA E ADORAÇÃO)\nSANTO, SANTO, SANTO É O SENHOR.\n(GLÓRIA AO QUE É SANTO)\n<final>SANTO, SANTO, SANTO É O SENHOR. <bis tipo="3x">',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'DEUS DE MARAVILHAS','DEUS DE MARAVILHAS','CORO\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES,\nAVIVA TUA OBRA SENHOR\n\nESSE É O DEUS QUE EU SIRVO\nELE SEMPRE SURPREENDE\nDEUS DE PODER\nELE USA QUEM ELE QUER\nSOBERANO ELE É, DEUS DE VITÓRIA\n\nMAS DEUS NUNCA MUDOU\nELE SEMPRE OPEROU\nDEUS DA GLÓRIA\n\nMAS DEUS NUNCA MUDOU\nELE SEMPRE OPEROU\nESSE É O DEUS QUE EU AMO\n\nCORO 2X\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA TUA OBRA SENHOR\n\nFINAL\nAVIVA TUA OBRA SENHOR','<coro>\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES,\nAVIVA TUA OBRA SENHOR\n\nESSE É O DEUS QUE EU SIRVO\nELE SEMPRE SURPREENDE\nDEUS DE PODER\nELE USA QUEM ELE QUER\nSOBERANO ELE É, DEUS DE VITÓRIA\n\nMAS DEUS NUNCA MUDOU\nELE SEMPRE OPEROU\nDEUS DA GLÓRIA\n\nMAS DEUS NUNCA MUDOU\nELE SEMPRE OPEROU\nESSE É O DEUS QUE EU AMO<coro tipo="2X">\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA\nÉ O DEUS DE MARAVILHAS\nQUE OPERA EM NOSSO MEIO\nVEM LIBERTANDO, TRANSFORMANDO\nOS CORAÇÕES, AVIVA TUA OBRA SENHOR\n<final>AVIVA TUA OBRA SENHOR',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'ELE É O LEÃO DA TRIBO DE JUDÁ','ELE É O LEÃO DA TRIBO DE JUDÁ','(2X)\nELE É O LEÃO DA TRIBO DE JUDÁ\nJESUS QUEBROU NOSSAS CADEIAS E NOS LIBERTOU\nELE É A ROCHA DA NOSSA VITÓRIA\nA NOSSA FORÇA EM TEMPOS DE FRAQUEZA\nUMA TORRE EM TEMPOS DE GUERRA\nOH, A ESPERANÇA DE ISRAEL\n\nFINAL\nOH, A ESPERANÇA DE ISRAEL','<bis tipo="2x">\nELE É O LEÃO DA TRIBO DE JUDÁ\nJESUS QUEBROU NOSSAS CADEIAS E NOS LIBERTOU\nELE É A ROCHA DA NOSSA VITÓRIA\nA NOSSA FORÇA EM TEMPOS DE FRAQUEZA\nUMA TORRE EM TEMPOS DE GUERRA\nOH, A ESPERANÇA DE ISRAEL\n<final>OH, A ESPERANÇA DE ISRAEL',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'EM MEIO À MULTIDÃO','EM MEIO À MULTIDÃO','EM MEIO À MULTIDÃO, SURGIU UMA MULHER\nDESEJANDO SE APROXIMAR DO SENHOR JESUS.\nSEU CORPO JÁ CANSADO E SEM FORÇAS PRA LUTAR,\nPELA FÉ ELA CHEGOU A LHE TOCAR.\n\nCORO\nE UM GRANDE MILAGRE ACONTECEU:\nELA FOI CURADA PELO FILHO DE DEUS.\nSUA FÉ A CONDUZIU QUANDO ELA OUVIU\nQUEM ERA JESUS E O QUE PODIA FAZER\nSOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.\n\nINSTRUMENTOS\n\nNÃO DESISTAS DE LUTAR, NÃO PERCAS TUA FÉ,\nO SENHOR VAI TE AJUDAR E VAI TE MANTER DE PÉ.\nROMPE TODAS AS BARREIRAS ATRAVÉS DA TUA FÉ,\nTOCA AGORA EM JESUS COMO FEZ AQUELA MULHER.\n\nCORO 2X\nE UM GRANDE MILAGRE ACONTECEU:\nELA FOI CURADA PELO FILHO DE DEUS.\nSUA FÉ A CONDUZIU QUANDO ELA OUVIU\nQUEM ERA JESUS E O QUE PODIA FAZER\nSOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.\n\nFINAL:\nSOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.','EM MEIO À MULTIDÃO, SURGIU UMA MULHER\nDESEJANDO SE APROXIMAR DO SENHOR JESUS.\nSEU CORPO JÁ CANSADO E SEM FORÇAS PRA LUTAR,\nPELA FÉ ELA CHEGOU A LHE TOCAR.<coro>\nE UM GRANDE MILAGRE ACONTECEU:\nELA FOI CURADA PELO FILHO DE DEUS.\nSUA FÉ A CONDUZIU QUANDO ELA OUVIU\nQUEM ERA JESUS E O QUE PODIA FAZER\nSOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.\n<instrumentos>\nNÃO DESISTAS DE LUTAR, NÃO PERCAS TUA FÉ,\nO SENHOR VAI TE AJUDAR E VAI TE MANTER DE PÉ.\nROMPE TODAS AS BARREIRAS ATRAVÉS DA TUA FÉ,\nTOCA AGORA EM JESUS COMO FEZ AQUELA MULHER.<coro tipo="2X">\nE UM GRANDE MILAGRE ACONTECEU:\nELA FOI CURADA PELO FILHO DE DEUS.\nSUA FÉ A CONDUZIU QUANDO ELA OUVIU\nQUEM ERA JESUS E O QUE PODIA FAZER\nSOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.\n<final>SOBRE A VIDA DE TODOS OS QUE NELE CRESSEM.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'ESTA É A MENSAGEM ETERNA DE DEUS','ESTA É A MENSAGEM ETERNA DE DEUS','ESTA É A MENSAGEM ETERNA DE DEUS:\nQUE JESUS CRISTO POR MIM JÁ MORREU,\nMAS ELE VIVO HOJE ESTÁ\nE BREVE DOS CÉUS VIRÁ ME BUSCAR (BIS)\n\nCORO\nMARANATA É O GRITO DA IGREJA,\nQUE VITORIOSA NOS CÉUS ENTRARÁ\nPARA HERDAR TUDO O QUE DEUS NOS DEU;\nO VENCEDOR DE DEUS, TUDO HERDARÁ (BIS)\n\nINSTRUMENTOS\n\nHOJE É TEMPO DE RECONSTRUÇÃO,\nDE VIGILÂNCIA E DE ORAÇÃO,\nÉ TEMPO DE OPORTUNIDADE,\nDE NOVA VIDA E FELICIDADE (BIS)\n\nFINAL\nMARANATA É O GRITO DA IGREJA,\nQUE VITORIOSA NOS CÉUS ENTRARÁ\nPARA HERDAR TUDO O QUE DEUS NOS DEU;\nO VENCEDOR DE DEUS, TUDO HERDARÁ (BIS)','ESTA É A MENSAGEM ETERNA DE DEUS:\nQUE JESUS CRISTO POR MIM JÁ MORREU,\nMAS ELE VIVO HOJE ESTÁ\nE BREVE DOS CÉUS VIRÁ ME BUSCAR (BIS)<coro>\nMARANATA É O GRITO DA IGREJA,\nQUE VITORIOSA NOS CÉUS ENTRARÁ\nPARA HERDAR TUDO O QUE DEUS NOS DEU;\nO VENCEDOR DE DEUS, TUDO HERDARÁ <bis>\n<instrumentos>\nHOJE É TEMPO DE RECONSTRUÇÃO,\nDE VIGILÂNCIA E DE ORAÇÃO,\nÉ TEMPO DE OPORTUNIDADE,\nDE NOVA VIDA E FELICIDADE <bis>\n<final>MARANATA É O GRITO DA IGREJA,\nQUE VITORIOSA NOS CÉUS ENTRARÁ\nPARA HERDAR TUDO O QUE DEUS NOS DEU;\nO VENCEDOR DE DEUS, TUDO HERDARÁ <bis>',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'EU CLAMO PELO SANGUE DE JESUS','EU CLAMO PELO SANGUE DE JESUS','EU CLAMO PELO SANGUE DE JESUS,\nQUE TRAZ A COMUNHÃO,\nLIBERTAÇÃO E PODER.\nENTREGO A TI, SENHOR,\nTODO O MEU SER.\n\nPURIFICA-ME, SENHOR,\nCOM TEU SANGUE REMIDOR.\nJUSTIFICA-ME, JESUS,\nCOM ESTE SANGUE\nQUE UM DIA DERRAMASTE\nNAQUELA CRUZ,\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.\n\nEU CLAMO PELO SANGUE DE JESUS,\nQUE TRAZ A COMUNHÃO,\nLIBERTAÇÃO E PODER.\nENTREGO A TI, SENHOR,\nTODO O MEU SER.\n\nPURIFICA-ME, SENHOR,\nCOM TEU SANGUE REMIDOR.\nJUSTIFICA-ME, JESUS,\nCOM ESTE SANGUE\nQUE UM DIA DERRAMASTE\nNAQUELA CRUZ,\n\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.','EU CLAMO PELO SANGUE DE JESUS,\nQUE TRAZ A COMUNHÃO,\nLIBERTAÇÃO E PODER.\nENTREGO A TI, SENHOR,\nTODO O MEU SER.\n\nPURIFICA-ME, SENHOR,\nCOM TEU SANGUE REMIDOR.\nJUSTIFICA-ME, JESUS,\nCOM ESTE SANGUE\nQUE UM DIA DERRAMASTE\nNAQUELA CRUZ,\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.\n\nEU CLAMO PELO SANGUE DE JESUS,\nQUE TRAZ A COMUNHÃO,\nLIBERTAÇÃO E PODER.\nENTREGO A TI, SENHOR,\nTODO O MEU SER.\n\nPURIFICA-ME, SENHOR,\nCOM TEU SANGUE REMIDOR.\nJUSTIFICA-ME, JESUS,\nCOM ESTE SANGUE\nQUE UM DIA DERRAMASTE\nNAQUELA CRUZ,\n\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.\nSÓ POR ME AMAR\nE VIDA ETERNA DAR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'EU TENHO UM AMIGO','EU TENHO UM AMIGO','EU TENHO UM AMIGO\nEM TODOS OS MOMENTOS FIEL A MIM;\nSER MARAVILHOSO,\nDE BRILHO CELESTE, AMOR SEM FIM;\nESSE AMIGO FIEL\nTEM O NOME MAIS DOCE QUE O MEL,\nESSE AMOR DE AMIGO PERFEITO\nNÃO POSSO DESCREVER,\nPOSSO SENTIR.\n\nSUA ALTURA É PERFEITA,\nSEUS CABELOS E OLHOS,\nBRILHO CELESTIAL;\nNA EXPRESSÃO DO SEU ROSTO\nO MAIS PERFEITO E PURO AMOR;\nÉ TODA EXPRESSÃO\nDO AMOR QUE BRILHA COMO O SOL,\nESSE AMOR DE AMIGO PERFEITO\nNÃO POSSO DESCREVER,\nPOSSO SENTIR.\n\nINSTRUMENTOS\n\nESSE AMIGO PERFEITO É JESUS,\nVESTIDO NA FORÇA DO SEU RESPLENDOR,\nCOROADO DE GLÓRIA E LOUVOR,\nFACE A FACE O VEREI COMO ELE É;\nVOLTARÁ, AFINAL,\nCOM OS ANJOS EM CORO CELESTIAL,\nJESUS É O AMIGO PERFEITO,\nNÃO POSSO DESCREVER, POSSO SENTIR;\nJESUS É O AMIGO PERFEITO.\n\nINSTRUMENTOS\n\nFINAL:\nJESUS É O AMIGO PERFEITO!','EU TENHO UM AMIGO\nEM TODOS OS MOMENTOS FIEL A MIM;\nSER MARAVILHOSO,\nDE BRILHO CELESTE, AMOR SEM FIM;\nESSE AMIGO FIEL\nTEM O NOME MAIS DOCE QUE O MEL,\nESSE AMOR DE AMIGO PERFEITO\nNÃO POSSO DESCREVER,\nPOSSO SENTIR.\n\nSUA ALTURA É PERFEITA,\nSEUS CABELOS E OLHOS,\nBRILHO CELESTIAL;\nNA EXPRESSÃO DO SEU ROSTO\nO MAIS PERFEITO E PURO AMOR;\nÉ TODA EXPRESSÃO\nDO AMOR QUE BRILHA COMO O SOL,\nESSE AMOR DE AMIGO PERFEITO\nNÃO POSSO DESCREVER,\nPOSSO SENTIR.\n<instrumentos>\nESSE AMIGO PERFEITO É JESUS,\nVESTIDO NA FORÇA DO SEU RESPLENDOR,\nCOROADO DE GLÓRIA E LOUVOR,\nFACE A FACE O VEREI COMO ELE É;\nVOLTARÁ, AFINAL,\nCOM OS ANJOS EM CORO CELESTIAL,\nJESUS É O AMIGO PERFEITO,\nNÃO POSSO DESCREVER, POSSO SENTIR;\nJESUS É O AMIGO PERFEITO.\n<instrumentos>\n<final>JESUS É O AMIGO PERFEITO!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'EU TENHO UM PAI (ADOÇÃO)','EU TENHO UM PAI (ADOÇÃO)','ME ENCONTRAVA ÓRFÃO,\nCOM UM VAZIO EM MINHA ALMA,\nTRANSFORMOU O MEU VIVER\nE ATRAVÉS DE JESUS\nRECEBI A ADOÇÃO\nE HOJE CLAMO: ABBA PAI.\n\nCORO\nHOJE EU TENHO UM PAI\nQUE É TÃO AMOROSO,\nHOJE EU TENHO UM PAI\nQUE É TÃO GLORIOSO,\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\n\nME ENCONTRAVA ÓRFÃO,\nCOM UM VAZIO EM MINHA ALMA,\nTRANSFORMOU O MEU VIVER\nE ATRAVÉS DE JESUS\nRECEBI A ADOÇÃO\nE HOJE CLAMO: ABBA PAI.\n\nCORO\nHOJE EU TENHO UM PAI\nQUE É TÃO AMOROSO,\nHOJE EU TENHO UM PAI\nQUE É TÃO GLORIOSO,\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\n\nFINAL:\nJESUS, TU ÉS O MELHOR QUE HÁ EM MIM,\nMUDASTE A MINHA VIDA E A MINHA HISTÓRIA;\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\nHOJE EU TENHO UM PAI, (EU TENHO UM PAI)\nHOJE EU TENHO UM PAI.','ME ENCONTRAVA ÓRFÃO,\nCOM UM VAZIO EM MINHA ALMA,\nTRANSFORMOU O MEU VIVER\nE ATRAVÉS DE JESUS\nRECEBI A ADOÇÃO\nE HOJE CLAMO: ABBA PAI.<coro>\nHOJE EU TENHO UM PAI\nQUE É TÃO AMOROSO,\nHOJE EU TENHO UM PAI\nQUE É TÃO GLORIOSO,\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\n\nME ENCONTRAVA ÓRFÃO,\nCOM UM VAZIO EM MINHA ALMA,\nTRANSFORMOU O MEU VIVER\nE ATRAVÉS DE JESUS\nRECEBI A ADOÇÃO\nE HOJE CLAMO: ABBA PAI.<coro>\nHOJE EU TENHO UM PAI\nQUE É TÃO AMOROSO,\nHOJE EU TENHO UM PAI\nQUE É TÃO GLORIOSO,\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\n<final>JESUS, TU ÉS O MELHOR QUE HÁ EM MIM,\nMUDASTE A MINHA VIDA E A MINHA HISTÓRIA;\nHOJE EU TENHO UM PAI\nQUE ENVIOU JESUS,\nQUE MORREU NA CRUZ\nPRA ME DAR O SEU AMOR (SEU AMOR).\nHOJE EU TENHO UM PAI, (EU TENHO UM PAI)\nHOJE EU TENHO UM PAI.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'FAZ-ME LEMBRAR','FAZ-ME LEMBRAR','(SERVAS)\nHOJE, AQUI, NO MOMENTO\nSÓ DEUS E EU;\nMINHA MENTE ESTÁ EM TI.\nVIM PEDIR PERDÃO\n\nPOR ME AFASTAR DAQUI E IR\nA UM LUGAR PRA ONDE EU\nNÃO QUERO MAIS VOLTAR.\n\nONDE EU PASSEI, NOS CAMINHOS\nPOR ONDE ANDEI,\nSENTI TRISTEZAS QUE ANTES\nNÃO EXPERIMENTEI.\nQUE FAZEM PARTE DA VIDA\nDOS QUE NÃO TÊM A TI.\nENTÃO VOLTEI, POIS SEI QUE\nTENHO UM LAR JUNTO A TI.\n\nCORO 2X\nFAZ-ME LEMBRAR\n(M) O QUANTO FUI FELIZ\nNESTE LUGAR. OS IMPOSSÍVEIS DOS HOMENS\nSÃO POSSÍVEIS PRA DEUS.\nSEI QUE TENS PODER PRA ME REFAZER.\n\nUM DIA AO TEU LADO É MELHOR\nDO QUE MIL NOUTRO LUGAR.\n\nINSTRUMENTOS\n\nONDE EU PASSEI, NOS CAMINHOS\nPOR ONDE ANDEI,\nSENTI TRISTEZAS QUE ANTES\nNÃO EXPERIMENTEI.\nQUE FAZEM PARTE DA VIDA\nDOS QUE NÃO TÊM A TI.\nENTÃO VOLTEI, POIS SEI QUE\nTENHO UM LAR JUNTO A TI.\n\nCORO 2X\nFAZ-ME LEMBRAR\n(M) O QUANTO FUI FELIZ\nNESTE LUGAR. OS IMPOSSÍVEIS DOS HOMENS\nSÃO POSSÍVEIS PRA DEUS.\nSEI QUE TENS PODER PRA ME REFAZER.\n\nUM DIA AO TEU LADO É MELHOR\nDO QUE MIL NOUTRO LUGAR.','<m>\nHOJE, AQUI, NO MOMENTO\nSÓ DEUS E EU;\nMINHA MENTE ESTÁ EM TI.\nVIM PEDIR PERDÃO\n\nPOR ME AFASTAR DAQUI E IR\nA UM LUGAR PRA ONDE EU\nNÃO QUERO MAIS VOLTAR.\n\nONDE EU PASSEI, NOS CAMINHOS\nPOR ONDE ANDEI,\nSENTI TRISTEZAS QUE ANTES\nNÃO EXPERIMENTEI.\nQUE FAZEM PARTE DA VIDA\nDOS QUE NÃO TÊM A TI.\nENTÃO VOLTEI, POIS SEI QUE\nTENHO UM LAR JUNTO A TI.<coro tipo="2X">\nFAZ-ME LEMBRAR\n<m> O QUANTO FUI FELIZ\nNESTE LUGAR. OS IMPOSSÍVEIS DOS HOMENS\nSÃO POSSÍVEIS PRA DEUS.\nSEI QUE TENS PODER PRA ME REFAZER.\n\nUM DIA AO TEU LADO É MELHOR\nDO QUE MIL NOUTRO LUGAR.\n<instrumentos>\nONDE EU PASSEI, NOS CAMINHOS\nPOR ONDE ANDEI,\nSENTI TRISTEZAS QUE ANTES\nNÃO EXPERIMENTEI.\nQUE FAZEM PARTE DA VIDA\nDOS QUE NÃO TÊM A TI.\nENTÃO VOLTEI, POIS SEI QUE\nTENHO UM LAR JUNTO A TI.<coro tipo="2X">\nFAZ-ME LEMBRAR\n<m> O QUANTO FUI FELIZ\nNESTE LUGAR. OS IMPOSSÍVEIS DOS HOMENS\nSÃO POSSÍVEIS PRA DEUS.\nSEI QUE TENS PODER PRA ME REFAZER.\n\nUM DIA AO TEU LADO É MELHOR\nDO QUE MIL NOUTRO LUGAR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'GADARENO','GADARENO','(SERVAS)\nERA UM HOMEM,\nMORANDO EM SEPULCROS,\nO GADARENO, LARGADO.\nOLHOS À VOLTA O RECRIMINAVAM,\nTODOS PASSAVAM A LARGO.\n\n(H) NINGUÉM SE IMPORTAVA COM A DOR\n(M) DO DESVALIDO INFELIZ.\nVIVIA SÓ, PRESO A CORRENTES,\nSEM IDENTIDADE, FERINDO-SE A SI.\n\n(H) FOI QUANDO, ENTÃO, DA OUTRA MARGEM SURGIU\n(M) AQUELE QUE VEIO A HISTÓRIA MUDAR.\n(H) DETENDO EM SI TODA AUTORIDADE\nNO CÉU, NA TERRA E NO MAR.\n\nORDENOU AO MAL QUE SE RETIRASSE\nQUEBRANDO O JULGO CRUEL,\n(M) DEVOLVENDO A PAZ E A FELICIDADE,\nLEVANDO-O DE VOLTA AOS SEUS.\n\nAUTORIDADE, PODER, MAJESTADE,\nSABEDORIA E TODA JUSTIÇA.\nGRAÇA E VERDADE.\nFORÇA E DOMÍNIO PELOS SÉCULOS\nDOS SÉCULOS, AMÉM!\nAMÉM! AMÉM! AMÉM!\n\nAUTORIDADE, PODER, MAJESTADE,\n(É JESUS!)\nSABEDORIA E TODA JUSTIÇA.\n(UH!)\nGRAÇA E VERDADE.\nFORÇA E DOMÍNIO PELOS SÉCULOS\nDOS SÉCULOS, AMÉM!\nAMÉM! AMÉM! AMÉM!','<m>\nERA UM HOMEM,\nMORANDO EM SEPULCROS,\nO GADARENO, LARGADO.\nOLHOS À VOLTA O RECRIMINAVAM,\nTODOS PASSAVAM A LARGO.\n\n<h> NINGUÉM SE IMPORTAVA COM A DOR\n<m> DO DESVALIDO INFELIZ.\nVIVIA SÓ, PRESO A CORRENTES,\nSEM IDENTIDADE, FERINDO-SE A SI.\n\n<h> FOI QUANDO, ENTÃO, DA OUTRA MARGEM SURGIU\n<m> AQUELE QUE VEIO A HISTÓRIA MUDAR.\n<h> DETENDO EM SI TODA AUTORIDADE\nNO CÉU, NA TERRA E NO MAR.\n\nORDENOU AO MAL QUE SE RETIRASSE\nQUEBRANDO O JULGO CRUEL,\n<m> DEVOLVENDO A PAZ E A FELICIDADE,\nLEVANDO-O DE VOLTA AOS SEUS.\n\nAUTORIDADE, PODER, MAJESTADE,\nSABEDORIA E TODA JUSTIÇA.\nGRAÇA E VERDADE.\nFORÇA E DOMÍNIO PELOS SÉCULOS\nDOS SÉCULOS, AMÉM!\nAMÉM! AMÉM! AMÉM!\n\nAUTORIDADE, PODER, MAJESTADE,\n(É JESUS!)\nSABEDORIA E TODA JUSTIÇA.\n(UH!)\nGRAÇA E VERDADE.\nFORÇA E DOMÍNIO PELOS SÉCULOS\nDOS SÉCULOS, AMÉM!\nAMÉM! AMÉM! AMÉM!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'JESUS QUERO TE OFERTAR (JESUS EU TE AMO)','JESUS QUERO TE OFERTAR (JESUS EU TE AMO)','JESUS QUERO TE OFERTAR\nO MEU CORAÇÃO\nO MELHOR QUE HÁ EM MIM.\n\nQUERO AO MUNDO CONTAR,\nA TODOS FALAR\nAS MARAVILHAS DO TEU AMOR\n\nPORQUE SANTO ÉS,\nMAJESTOSO EM PODER,\nE OS ANJOS PROCLAMEM\nNA GLÓRIA PARA SEMPRE\nEU QUERO DIZER:\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA SUA PRESENÇA MUDOU\nO MEU VIVER.\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA MINHA ALEGRIA SERÁ,\nUM DIA, CONTIGO ESTAR.\nINSTRUMENTOS\n\nJESUS QUERO ME AJOELHAR\nPOR TEU SANGUE CLAMAR\nJUNTINHO AOS TEUS PÉS,\n\nQUERO TUA VOZ ESCUTAR,\nVEM ME TOCAR,\nPOIS SEI QUEM TU ÉS\n\nÉS O MEU SALVADOR\nE EM TUDO VENCEU POR MIM,\nTEU AMOR ME FAZ CANTAR,\nSOU DEPENDENTE DE TI.\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA SUA PRESENÇA MUDOU\nO MEU VIVER.\n\nFINAL\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA MINHA ALEGRIA SERÁ,\nUM DIA, CONTIGO ESTAR.','JESUS QUERO TE OFERTAR\nO MEU CORAÇÃO\nO MELHOR QUE HÁ EM MIM.\n\nQUERO AO MUNDO CONTAR,\nA TODOS FALAR\nAS MARAVILHAS DO TEU AMOR\n\nPORQUE SANTO ÉS,\nMAJESTOSO EM PODER,\nE OS ANJOS PROCLAMEM\nNA GLÓRIA PARA SEMPRE\nEU QUERO DIZER:\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA SUA PRESENÇA MUDOU\nO MEU VIVER.\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA MINHA ALEGRIA SERÁ,\nUM DIA, CONTIGO ESTAR.\n<instrumentos>\nJESUS QUERO ME AJOELHAR\nPOR TEU SANGUE CLAMAR\nJUNTINHO AOS TEUS PÉS,\n\nQUERO TUA VOZ ESCUTAR,\nVEM ME TOCAR,\nPOIS SEI QUEM TU ÉS\n\nÉS O MEU SALVADOR\nE EM TUDO VENCEU POR MIM,\nTEU AMOR ME FAZ CANTAR,\nSOU DEPENDENTE DE TI.\n\nJESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA SUA PRESENÇA MUDOU\nO MEU VIVER.\n<final>JESUS EU TE AMO\n(EU TE AMO)\nOH! COMO EU AMO\n(OH COMO EU AMO)\nA MINHA ALEGRIA SERÁ,\nUM DIA, CONTIGO ESTAR.',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'JESUS, O AMIGO INCOMPARÁVEL','JESUS, O AMIGO INCOMPARÁVEL','JESUS, O AMIGO INCOMPARÁVEL,\nJESUS, O AMOR INEXPLICÁVEL,\nJESUS, A VIDA QUE VENCEU A MORTE\nE VOLTARÁ PRA ME BUSCAR.\n\nJESUS, O ALICERCE DE MINH''ALMA,\nJESUS, QUE CONSOLA E ME ACALMA,\nJESUS, O FILHO DE DEUS\nMEU NOME VAI CHAMAR.\n\nCORO\nENTÃO ENFIM VEREI O MEU REI,\nO PRÓPRIO AMOR QUE ME SALVOU,\nEU NÃO DESISTIREI, A LUTA ENFRENTAREI.\n\nINSTRUMENTOS\n\nJESUS, O ALICERCE DE MINH''ALMA,\nJESUS, QUE CONSOLA E ME ACALMA,\nJESUS, O FILHO DE DEUS\nMEU NOME VAI CHAMAR.\n\nCORO 2X\nENTÃO ENFIM VEREI O MEU REI,\nO PRÓPRIO AMOR QUE ME SALVOU,\nEU NÃO DESISTIREI, A LUTA ENFRENTAREI.\n\nFINAL\nVITÓRIA EU TEREI! (EU TEREI!)','JESUS, O AMIGO INCOMPARÁVEL,\nJESUS, O AMOR INEXPLICÁVEL,\nJESUS, A VIDA QUE VENCEU A MORTE\nE VOLTARÁ PRA ME BUSCAR.\n\nJESUS, O ALICERCE DE MINH''ALMA,\nJESUS, QUE CONSOLA E ME ACALMA,\nJESUS, O FILHO DE DEUS\nMEU NOME VAI CHAMAR.<coro>\nENTÃO ENFIM VEREI O MEU REI,\nO PRÓPRIO AMOR QUE ME SALVOU,\nEU NÃO DESISTIREI, A LUTA ENFRENTAREI.\n<instrumentos>\nJESUS, O ALICERCE DE MINH''ALMA,\nJESUS, QUE CONSOLA E ME ACALMA,\nJESUS, O FILHO DE DEUS\nMEU NOME VAI CHAMAR.<coro tipo="2X">\nENTÃO ENFIM VEREI O MEU REI,\nO PRÓPRIO AMOR QUE ME SALVOU,\nEU NÃO DESISTIREI, A LUTA ENFRENTAREI.\n<final>VITÓRIA EU TEREI! (EU TEREI!)',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'JESUS, O MISTÉRIO REVELADO','JESUS, O MISTÉRIO REVELADO','JESUS, O MISTÉRIO REVELADO,\nQUE ALIMENTA A MINHA ALMA;\nELE É O MEU TESOURO,\nÉ A MINHA ESPERANÇA.\n\nCORO\nESTE MISTÉRIO ME TRANSFORMOU,\nESTE MISTÉRIO MINHA VIDA MUDOU,\nESTE MISTÉRIO É TUDO PRA MIM: JESUS!\n\nINSTRUMENTOS\n\nJESUS QUER A TI SE REVELAR,\nQUER ALIMENTAR TUA ALMA;\nABRA O TEU CORAÇÃO\nE RECEBA A SALVAÇÃO.\n\nCORO 2X\nESTE MISTÉRIO ME TRANSFORMOU,\nESTE MISTÉRIO MINHA VIDA MUDOU,\nESTE MISTÉRIO É TUDO PRA MIM: JESUS!\n\nFINAL\nESTE MISTÉRIO É TUDO PRA MIM: JESUS!','JESUS, O MISTÉRIO REVELADO,\nQUE ALIMENTA A MINHA ALMA;\nELE É O MEU TESOURO,\nÉ A MINHA ESPERANÇA.<coro>\nESTE MISTÉRIO ME TRANSFORMOU,\nESTE MISTÉRIO MINHA VIDA MUDOU,\nESTE MISTÉRIO É TUDO PRA MIM: JESUS!\n<instrumentos>\nJESUS QUER A TI SE REVELAR,\nQUER ALIMENTAR TUA ALMA;\nABRA O TEU CORAÇÃO\nE RECEBA A SALVAÇÃO.<coro tipo="2X">\nESTE MISTÉRIO ME TRANSFORMOU,\nESTE MISTÉRIO MINHA VIDA MUDOU,\nESTE MISTÉRIO É TUDO PRA MIM: JESUS!\n<final>ESTE MISTÉRIO É TUDO PRA MIM: JESUS!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'MARANATA (EM BREVE, MUI BREVE)','MARANATA (EM BREVE, MUI BREVE)','EM BREVE, MUI BREVE O VEREI,\nNO CORAL CELESTIAL ESTAREI\nCOM OS ANJOS CANTANDO AO REDOR\nDO SEU TRONO DE GLÓRIA.\n\nCONTEMPLAR TODO O SEU ESPLENDOR,\nBEM DE PERTO SENTIR ESSE GRANDE AMOR;\nEM UMA SÓ VOZ PROCLAMAR:\nSANTO, SANTO É O SENHOR.\n\nANSEIO PELAS PORTAS ENTRAR,\nNAS RUAS DE OURO ANDAR\nE ABRAÇAR AQUELE QUE FOI, QUE É E QUE VIRÁ.\n\nPODEROSO DEUS, SONHO TI ENCONTRAR;\nALELUIA DOU, PREPARADO ESTOU PARA SUBIR,\nANSEIO MORAR NO LUGAR DE\nPAZ, ESTÁ MESMA PAZ QUE\nENCONTRO EM TI.\nINSTRUMENTOS\n\nEM BREVE, MUI BREVE O VEREI,\nNO CORAL CELESTIAL ESTAREI\nCOM OS ANJOS CANTANDO AO REDOR\nDO SEU TRONO DE GLÓRIA.\n\nCONTEMPLAR TODO O SEU ESPLENDOR,\nBEM DE PERTO SENTIR ESSE GRANDE AMOR;\nEM UMA SÓ VOZ PROCLAMAR:\nSANTO, SANTO É O SENHOR.\n\nANSEIO PELAS PORTAS ENTRAR,\nNAS RUAS DE OURO ANDAR\nE ABRAÇAR AQUELE QUE FOI, QUE É E QUE VIRÁ.\n\nPODEROSO DEUS, SONHO TI ENCONTRAR;\nALELUIA DOU, PREPARADO ESTOU PARA SUBIR,\nANSEIO MORAR NO LUGAR DE\nPAZ, ESTÁ MESMA PAZ QUE\nENCONTRO EM TI.\n\nFINAL\nMARANATA! MARANATA! ORA VEM, ORA VEM!\n(SENHOR JESUS)\nORA, VEM! ORA, VEM! ORA VEM, ORA VEM!\n(SENHOR JESUS)\nMARANATA, MARANATA, ORA VEM, ORA VEM!\nMARANATA, MARANATA, ORA VEM,\nSENHOR JESUS!','EM BREVE, MUI BREVE O VEREI,\nNO CORAL CELESTIAL ESTAREI\nCOM OS ANJOS CANTANDO AO REDOR\nDO SEU TRONO DE GLÓRIA.\n\nCONTEMPLAR TODO O SEU ESPLENDOR,\nBEM DE PERTO SENTIR ESSE GRANDE AMOR;\nEM UMA SÓ VOZ PROCLAMAR:\nSANTO, SANTO É O SENHOR.\n\nANSEIO PELAS PORTAS ENTRAR,\nNAS RUAS DE OURO ANDAR\nE ABRAÇAR AQUELE QUE FOI, QUE É E QUE VIRÁ.\n\nPODEROSO DEUS, SONHO TI ENCONTRAR;\nALELUIA DOU, PREPARADO ESTOU PARA SUBIR,\nANSEIO MORAR NO LUGAR DE\nPAZ, ESTÁ MESMA PAZ QUE\nENCONTRO EM TI.\n<instrumentos>\nEM BREVE, MUI BREVE O VEREI,\nNO CORAL CELESTIAL ESTAREI\nCOM OS ANJOS CANTANDO AO REDOR\nDO SEU TRONO DE GLÓRIA.\n\nCONTEMPLAR TODO O SEU ESPLENDOR,\nBEM DE PERTO SENTIR ESSE GRANDE AMOR;\nEM UMA SÓ VOZ PROCLAMAR:\nSANTO, SANTO É O SENHOR.\n\nANSEIO PELAS PORTAS ENTRAR,\nNAS RUAS DE OURO ANDAR\nE ABRAÇAR AQUELE QUE FOI, QUE É E QUE VIRÁ.\n\nPODEROSO DEUS, SONHO TI ENCONTRAR;\nALELUIA DOU, PREPARADO ESTOU PARA SUBIR,\nANSEIO MORAR NO LUGAR DE\nPAZ, ESTÁ MESMA PAZ QUE\nENCONTRO EM TI.\n<final>MARANATA! MARANATA! ORA VEM, ORA VEM!\n(SENHOR JESUS)\nORA, VEM! ORA, VEM! ORA VEM, ORA VEM!\n(SENHOR JESUS)\nMARANATA, MARANATA, ORA VEM, ORA VEM!\nMARANATA, MARANATA, ORA VEM,\nSENHOR JESUS!',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'NÃO HÁ DEUS COMO O NOSSO DEUS','NÃO HÁ DEUS COMO O NOSSO DEUS','(2X)\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.\n\nUMA NAÇÃO ESCOLHIDA POR TI\nPÔDE VER O PODER DE TUAS MÃOS.\nCOM BRAÇO FORTE GUIAS-TE TEU POVO,\nPROVESTE A ELES O PÃO.\n\nDE DIA UMA NUVEM OS COBRIA O SOL,\nDE NOITE CHAMAS DE FOGO.\nAS ÁGUAS AMARGAS TRANSFORMOU EM DOCE\nE DESSENDENTOU TODO O POVO.\n\n(2X)\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.\n\nCIDADES MURADAS, EXÉRCITO ARMADO,\nVALENTES GIGANTES TOMBARAM AO CHÃO.\nRIOS E MARES ABRISTE PASSAGEM,\nSOCORRO, SUSTENTO E PROVISÃO.\n\nASSIM TU TENS FEITO AINDA HOJE\nÓ DEUS, TODO PODEROSO.\nAOS TEUS SERVOS TEM DEMONSTRADO FAVOR,\nNOSSOS LÁBIOS ENTOAM LOUVOR.\n\nFINAL 4X\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.','<bis tipo="2x">\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.\n\nUMA NAÇÃO ESCOLHIDA POR TI\nPÔDE VER O PODER DE TUAS MÃOS.\nCOM BRAÇO FORTE GUIAS-TE TEU POVO,\nPROVESTE A ELES O PÃO.\n\nDE DIA UMA NUVEM OS COBRIA O SOL,\nDE NOITE CHAMAS DE FOGO.\nAS ÁGUAS AMARGAS TRANSFORMOU EM DOCE\nE DESSENDENTOU TODO O POVO.\n\n<bis tipo="2x">\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.\n\nCIDADES MURADAS, EXÉRCITO ARMADO,\nVALENTES GIGANTES TOMBARAM AO CHÃO.\nRIOS E MARES ABRISTE PASSAGEM,\nSOCORRO, SUSTENTO E PROVISÃO.\n\nASSIM TU TENS FEITO AINDA HOJE\nÓ DEUS, TODO PODEROSO.\nAOS TEUS SERVOS TEM DEMONSTRADO FAVOR,\nNOSSOS LÁBIOS ENTOAM LOUVOR.\n<final>4X\nNÃO HÁ DEUS COMO O NOSSO DEUS,\nNÃO HÁ DEUS, COMO O SENHOR.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'O ESPÍRITO DO SENHOR VEM SOBRE MIM','O ESPÍRITO DO SENHOR VEM SOBRE MIM','O ESPÍRITO DO SENHOR VEM SOBRE MIM.\nO ESPÍRITO DO SENHOR VEM SOBRE MIM.\nO ESPÍRITO DE SABEDORIA\nE DE INTELIGÊNCIA,\nO ESPÍRITO DE CONSELHO\nE DE FORTALEZA,\nO ESPÍRITO DE CONHECIMENTO\nE DE TEMOR DO SENHOR,\nO ESPÍRITO DO SENHOR VEM SOBRE MIM.\n\nNADA TEMEREI, PRONTO ESTAREI,\nPOIS O ESPÍRITO DO SENHOR VEM SOBRE MIM.\nMARANATA, JESUS VEM!\nORA VEM, SENHOR JESUS!\nCOM O ESPÍRITO DO SENHOR EU SUBIREI, (EU SUBIREI)\nCOM O ESPÍRITO DO SENHOR EU SUBIREI, (EU SUBIREI)\n\nFINAL\nCOM O ESPÍRITO DO SENHOR EU SUBIREI.','O ESPÍRITO DO SENHOR VEM SOBRE MIM.\nO ESPÍRITO DO SENHOR VEM SOBRE MIM.\nO ESPÍRITO DE SABEDORIA\nE DE INTELIGÊNCIA,\nO ESPÍRITO DE CONSELHO\nE DE FORTALEZA,\nO ESPÍRITO DE CONHECIMENTO\nE DE TEMOR DO SENHOR,\nO ESPÍRITO DO SENHOR VEM SOBRE MIM.\n\nNADA TEMEREI, PRONTO ESTAREI,\nPOIS O ESPÍRITO DO SENHOR VEM SOBRE MIM.\nMARANATA, JESUS VEM!\nORA VEM, SENHOR JESUS!\nCOM O ESPÍRITO DO SENHOR EU SUBIREI, (EU SUBIREI)\nCOM O ESPÍRITO DO SENHOR EU SUBIREI, (EU SUBIREI)\n<final>COM O ESPÍRITO DO SENHOR EU SUBIREI.',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'OS OLHOS DA FÉ','OS OLHOS DA FÉ','SENHOR, EU PRECISO VER\nCOM OS OLHOS DA FÉ,\nSÓ A TUA MÃO COLOCA-ME DE PÉ\nPRA CONTINUAR A CONFIAR.\n\nSENHOR, AS CIRCUNSTÂNCIAS\nQUEREM ME CEGAR,\nAS LUTAS VÊM PRA ME DESANIMAR\nDE CONTINUAR A CONFIAR.\n\nPOIS QUANDO TU ABRES MEUS OLHOS DA FÉ\nVEJO QUE SEMPRE ME PUSESTE DE PÉ,\nMUITAS PROMESSAS A MIM JÁ CUMPRISTE.\nAMOR IGUAL AO TEU NÃO EXISTE.\n\nCORO\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR,\nSEI QUE TUAS PROMESSAS VÃO SE CUMPRIR;\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR\nPORQUE NÃO ÉS HOMEM PARA MENTIR;\nTU NÃO MUDASTE, TU NUNCA FALHASTE,\nEU CREIO EM TI.\n\nINSTRUMENTOS\n\nPOIS QUANDO TU ABRES MEUS OLHOS DA FÉ\nVEJO QUE SEMPRE ME PUSESTE DE PÉ,\nMUITAS PROMESSAS A MIM JÁ CUMPRISTE.\nAMOR IGUAL AO TEU NÃO EXISTE.\n\nCORO\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR,\nSEI QUE TUAS PROMESSAS VÃO SE CUMPRIR;\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR\nPORQUE NÃO ÉS HOMEM PARA MENTIR;\nTU NÃO MUDASTE, TU NUNCA FALHASTE,\nEU CREIO EM TI.\n\nFINAL\nEU CREIO EM TI, EU CREIO EM TI.','SENHOR, EU PRECISO VER\nCOM OS OLHOS DA FÉ,\nSÓ A TUA MÃO COLOCA-ME DE PÉ\nPRA CONTINUAR A CONFIAR.\n\nSENHOR, AS CIRCUNSTÂNCIAS\nQUEREM ME CEGAR,\nAS LUTAS VÊM PRA ME DESANIMAR\nDE CONTINUAR A CONFIAR.\n\nPOIS QUANDO TU ABRES MEUS OLHOS DA FÉ\nVEJO QUE SEMPRE ME PUSESTE DE PÉ,\nMUITAS PROMESSAS A MIM JÁ CUMPRISTE.\nAMOR IGUAL AO TEU NÃO EXISTE.<coro>\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR,\nSEI QUE TUAS PROMESSAS VÃO SE CUMPRIR;\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR\nPORQUE NÃO ÉS HOMEM PARA MENTIR;\nTU NÃO MUDASTE, TU NUNCA FALHASTE,\nEU CREIO EM TI.\n<instrumentos>\nPOIS QUANDO TU ABRES MEUS OLHOS DA FÉ\nVEJO QUE SEMPRE ME PUSESTE DE PÉ,\nMUITAS PROMESSAS A MIM JÁ CUMPRISTE.\nAMOR IGUAL AO TEU NÃO EXISTE.<coro>\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR,\nSEI QUE TUAS PROMESSAS VÃO SE CUMPRIR;\nPOSSO CRER E CONFIAR,\nPOSSO CRER E DESCANSAR\nPORQUE NÃO ÉS HOMEM PARA MENTIR;\nTU NÃO MUDASTE, TU NUNCA FALHASTE,\nEU CREIO EM TI.\n<final>EU CREIO EM TI, EU CREIO EM TI.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'PAI, REUNIDOS ESTAMOS (ALELUIA AO CORDEIRO)','PAI, REUNIDOS ESTAMOS (ALELUIA AO CORDEIRO)','PAI, REUNIDOS ESTAMOS\nPRA TE ADORAR,\nLOUVANDO EM UMA SÓ VOZ,\nTEUS FILHOS SOMOS,\nREMIDOS POR TI,\nDA MORTE SALVOS, ENFIM.\n\nNÃO HÁ PALAVRAS PARA\nAGRADECER-TE,\nNEM EXPRESSAR TÃO\nIMENSO AMOR,\nMAS ERGUEREI MINHA VOZ\nEM UM SÓ LOUVOR,\nCOM TODO O MEU SER.\n\nCORO\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n\nPAI, POR TEU INFINDO\nE IMENSO AMOR,\nNOS DESTE A SALVAÇÃO,\nTEUS FILHOS SOMOS\nSALVOS POR TI,\nPROSTRADOS EM ORAÇÃO.\n\nVEM DERRAMAR TEU SANTO\nE DOCE AMOR EM NÓS\nPRA SERMOS LUZ NESTE MUNDO AQUI,\nNAÇÕES E POVOS VERÃO\nTUA GLÓRIA REINAR E TE ADORARÃO.\n\nCORO\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n\nCHEIOS DE GRATIDÃO,\nTODOS PROCLAMEM QUE\nTU ÉS SENHOR E REI.\n\nCORO\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO REI.\n\nCORO\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n\nFINAL:\nE LOUVANDO AO NOSSO SALVADOR.\nE LOUVANDO AO NOSSO SALVADOR.\nNOSSO DEUS REINARÁ.','PAI, REUNIDOS ESTAMOS\nPRA TE ADORAR,\nLOUVANDO EM UMA SÓ VOZ,\nTEUS FILHOS SOMOS,\nREMIDOS POR TI,\nDA MORTE SALVOS, ENFIM.\n\nNÃO HÁ PALAVRAS PARA\nAGRADECER-TE,\nNEM EXPRESSAR TÃO\nIMENSO AMOR,\nMAS ERGUEREI MINHA VOZ\nEM UM SÓ LOUVOR,\nCOM TODO O MEU SER.<coro>\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n\nPAI, POR TEU INFINDO\nE IMENSO AMOR,\nNOS DESTE A SALVAÇÃO,\nTEUS FILHOS SOMOS\nSALVOS POR TI,\nPROSTRADOS EM ORAÇÃO.\n\nVEM DERRAMAR TEU SANTO\nE DOCE AMOR EM NÓS\nPRA SERMOS LUZ NESTE MUNDO AQUI,\nNAÇÕES E POVOS VERÃO\nTUA GLÓRIA REINAR E TE ADORARÃO.<coro>\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n\nCHEIOS DE GRATIDÃO,\nTODOS PROCLAMEM QUE\nTU ÉS SENHOR E REI.<coro>\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO REI.<coro>\nALELUIA, ALELUIA,\nALELUIA AO CORDEIRO,\nALELUIA, ALELUIA\nPELO SANGUE QUE VERTEU;\nTODA TERRA, TODA TRIBO,\nTODA LÍNGUA, TODO CÉU,\nDANDO GLÓRIA, DANDO HONRA\nE LOUVANDO AO NOSSO SALVADOR.\n<final>E LOUVANDO AO NOSSO SALVADOR.\nE LOUVANDO AO NOSSO SALVADOR.\nNOSSO DEUS REINARÁ.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'PERANTE A TUA GRANDEZA','PERANTE A TUA GRANDEZA','PERANTE A TUA GRANDEZA,\nME SINTO TÃO PEQUENO.\nMINHA FORÇA SE ESVANECE,\nO MEU CORPO ESTREMECE, SENHOR.\n\nTU ME SUSTENTAS PARA EU NÃO CAIR,\nERGUES MEUS JOELHOS, ME COLOCAS DE PÉ.\nME SINTO SEGURO EM OUVIR TUA PALAVRA,\nDIZENDO: "NÃO TEMAS, FILHO MEU."\n\nCOMO HOMEM, SOFRI E CHOREI;\nMUITAS NOITES EM CLARO PASSEI.\nPOR AMOR A TI, FILHO MEU.\nNEGUEI MINHA VONTADE.\n\nINSTRUMENTOS\n\nÓ JESUS, EU RECONHEÇO (TUA BONDADE!)\nTEU AMOR E TUA BONDADE (E PROSTRADO)\nE, PROSTRADO, TE ADORO\nPRA FAZER TUA VONTADE, SENHOR.\n\nPOIS ME SUSTENTAS PARA EU NÃO CAIR,\nERGUES MEUS JOELHOS, ME COLOCAS DE PÉ.\nME SINTO SEGURO EM OUVIR TUA PALAVRA,\nDIZENDO: "NÃO TEMAS, FILHO MEU."\n\nCOMO HOMEM, SOFRI E CHOREI;\nMUITAS NOITES EM CLARO PASSEI.\n\nFINAL 2X\nPOR AMOR A TI, FILHO MEU.\nNEGUEI MINHA VONTADE.','PERANTE A TUA GRANDEZA,\nME SINTO TÃO PEQUENO.\nMINHA FORÇA SE ESVANECE,\nO MEU CORPO ESTREMECE, SENHOR.\n\nTU ME SUSTENTAS PARA EU NÃO CAIR,\nERGUES MEUS JOELHOS, ME COLOCAS DE PÉ.\nME SINTO SEGURO EM OUVIR TUA PALAVRA,\nDIZENDO: "NÃO TEMAS, FILHO MEU."\n\nCOMO HOMEM, SOFRI E CHOREI;\nMUITAS NOITES EM CLARO PASSEI.\nPOR AMOR A TI, FILHO MEU.\nNEGUEI MINHA VONTADE.\n<instrumentos>\nÓ JESUS, EU RECONHEÇO (TUA BONDADE!)\nTEU AMOR E TUA BONDADE (E PROSTRADO)\nE, PROSTRADO, TE ADORO\nPRA FAZER TUA VONTADE, SENHOR.\n\nPOIS ME SUSTENTAS PARA EU NÃO CAIR,\nERGUES MEUS JOELHOS, ME COLOCAS DE PÉ.\nME SINTO SEGURO EM OUVIR TUA PALAVRA,\nDIZENDO: "NÃO TEMAS, FILHO MEU."\n\nCOMO HOMEM, SOFRI E CHOREI;\nMUITAS NOITES EM CLARO PASSEI.\n<final>2X\nPOR AMOR A TI, FILHO MEU.\nNEGUEI MINHA VONTADE.',(select id from coletanea where nome = 'LOUVORES AVULSOS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL,'SENHOR, TÃO PEQUENO SOU','SENHOR, TÃO PEQUENO SOU','SENHOR, TÃO PEQUENO SOU\nMAS O SENHOR, CUIDA DE MIM\nSENHOR, ÀS VEZES, NEM SEI FALAR\nMAS O SENHOR OUVE A MINHA ORAÇÃO\nABENÇOA MEU PAI, MINHA MÃE\nMEUS IRMÃOS, MINHA FAMÍLIA\nPARA ESTARMOS TODOS OS DIAS NA TUA CASA\n\nCORO\nBATIZA-ME COM O ESPÍRITO SANTO\nABRE OS MEUS OLHOS PRA QUE EU POSSA VER\nA TUA GLÓRIA ENCHENDO TODA A IGREJA\nQUERO A TI DEDICAR O MEU LOUVOR\nE DIZER O QUANTO EU TE AMO\nPOIS, O SENHOR É O MEU DEUS FORTE\n\nINSTRUMENTOS\n\nSENHOR, TÃO PEQUENO SOU\nMAS O SENHOR, CUIDA DE MIM\nSENHOR, ÀS VEZES, NEM SEI FALAR\nMAS O SENHOR OUVE A MINHA ORAÇÃO\nABENÇOA MEU PAI, MINHA MÃE\nMEUS IRMÃOS, MINHA FAMÍLIA\nPARA ESTARMOS TODOS OS DIAS NA TUA CASA\n\nCORO\nBATIZA-ME COM O ESPÍRITO SANTO\nABRE OS MEUS OLHOS PRA QUE EU POSSA VER\nA TUA GLÓRIA ENCHENDO TODA A IGREJA\nQUERO A TI DEDICAR O MEU LOUVOR\nE DIZER O QUANTO EU TE AMO\nPOIS, O SENHOR É O MEU DEUS FORTE','SENHOR, TÃO PEQUENO SOU\nMAS O SENHOR, CUIDA DE MIM\nSENHOR, ÀS VEZES, NEM SEI FALAR\nMAS O SENHOR OUVE A MINHA ORAÇÃO\nABENÇOA MEU PAI, MINHA MÃE\nMEUS IRMÃOS, MINHA FAMÍLIA\nPARA ESTARMOS TODOS OS DIAS NA TUA CASA<coro>\nBATIZA-ME COM O ESPÍRITO SANTO\nABRE OS MEUS OLHOS PRA QUE EU POSSA VER\nA TUA GLÓRIA ENCHENDO TODA A IGREJA\nQUERO A TI DEDICAR O MEU LOUVOR\nE DIZER O QUANTO EU TE AMO\nPOIS, O SENHOR É O MEU DEUS FORTE\n<instrumentos>\nSENHOR, TÃO PEQUENO SOU\nMAS O SENHOR, CUIDA DE MIM\nSENHOR, ÀS VEZES, NEM SEI FALAR\nMAS O SENHOR OUVE A MINHA ORAÇÃO\nABENÇOA MEU PAI, MINHA MÃE\nMEUS IRMÃOS, MINHA FAMÍLIA\nPARA ESTARMOS TODOS OS DIAS NA TUA CASA<coro>\nBATIZA-ME COM O ESPÍRITO SANTO\nABRE OS MEUS OLHOS PRA QUE EU POSSA VER\nA TUA GLÓRIA ENCHENDO TODA A IGREJA\nQUERO A TI DEDICAR O MEU LOUVOR\nE DIZER O QUANTO EU TE AMO\nPOIS, O SENHOR É O MEU DEUS FORTE',(select id from coletanea where nome = 'LOUVORES AVULSOS CIAS - MANUAL'),'PT-BR',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
